PROGRAM ST050_SVALTHANTERING
VAR
    steg        : INT := 0;
    trigAuto    : R_TRIG;
    tmrArbete   : TON;
    tmrNarvaro  : TON;
    xArbetar    : BOOL := FALSE;
    xVantarKort : BOOL := FALSE;
    xTomt       : BOOL := FALSE;
    xLarm       : BOOL := FALSE;
END_VAR

trigAuto(CLK := SYS_AUTO);

(* Svalt ar INGET fel. Materialbrist uppstroms ar ett vantlage: stationen sager
   ifran med ST050_STA_STARVED och lamnar samlingslarmet lagt. Ett larm pa
   materialbrist stannar hela linan, operatoren far kvittera nagot som aldrig
   var ett fel, och tillgangligheten mats fel resten av skiftet. *)
xTomt := ST050_MAG_EMPTY OR (ST050_MAG_LEVEL <= 0);

(* Magasinet rymmer 60 kort. Ett varde over rymden ar ett GIVARFEL och alltsa
   ett verkligt fel: det ar inte gott om material, det ar en givare som ljuger. *)
IF ST050_MAG_LEVEL > 60 THEN
    xLarm := TRUE;
END_IF;

(* Bandet gar men inget kort har natt stationslaget trots att magasinet sager
   att material finns: nagot har fastnat mellan magasin och station. Kortet ar
   233 mm och bandet gar 0,35 m/s, sa ett kort passerar narvarogivaren pa
   233/350 = 0,666 s; 5,0 s ar over sju ganger sa lang och kan inte forvaxlas
   med ett kort som bara ar pa vag. *)
xVantarKort := ST050_CNV_RUN AND NOT ST050_PRT_PRS AND NOT xTomt;
tmrNarvaro(IN := xVantarKort, PT := T#5s);
IF tmrNarvaro.Q THEN
    xLarm := TRUE;
END_IF;

(* Larmet ar latchat och slapper bara pa en manuell handling: stationen ur och
   tillbaka i automatlage. Vantlaget slapper daremot av sig sjalvt nar
   materialet kommer tillbaka och kraver ingen kvittens alls. *)
IF trigAuto.Q THEN
    xLarm := FALSE;
END_IF;
SYS_ALARM := xLarm;

(* Arbetstiden 10,0 s plus kortbytet cirka 2,0 s ger takten 12,0 s per kort. *)
xArbetar := (steg = 1);
tmrArbete(IN := xArbetar, PT := T#10s);

IF NOT SYS_AUTO OR xLarm THEN
    ST050_CNV_RUN := FALSE;
    ST050_STA_BUSY := FALSE;
    ST050_STA_DONE := FALSE;
    steg := 0;
ELSE
    CASE steg OF
        0:
            ST050_STA_BUSY := FALSE;
            ST050_STA_DONE := FALSE;
            IF ST050_PRT_PRS THEN
                ST050_CNV_RUN := FALSE;
                ST050_STA_STARVED := FALSE;
                steg := 1;
            ELSIF xTomt THEN
                ST050_CNV_RUN := FALSE;
                ST050_STA_STARVED := TRUE;
            ELSE
                ST050_CNV_RUN := TRUE;
            END_IF;
        1:
            ST050_STA_BUSY := TRUE;
            IF tmrArbete.Q THEN
                ST050_STA_BUSY := FALSE;
                ST050_STA_DONE := TRUE;
                ST050_CNV_RUN := TRUE;
                steg := 2;
            END_IF;
        2:
            IF NOT ST050_PRT_PRS THEN
                ST050_STA_DONE := FALSE;
                steg := 0;
            END_IF;
    ELSE
        steg := 0;
    END_CASE;
END_IF;
END_PROGRAM

